From 9e24546db5e97b39212b92955ed0bd733702eddf Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:07:45 +0100
Subject: [PATCH] applets/webbrowser: offer to visit pages with untrusted
 certificates

The widget had no way past a certificate error, so intranet pages with
self-signed certificates could only show Chromium's error page. It now
shows the error with a "Visit Anyway" button that loads the page.

BUG: 515640
---
 applets/webbrowser/qml/main.qml | 40 +++++++++++++++++++++++++++++++++
 1 file changed, 40 insertions(+)

diff --git a/applets/webbrowser/qml/main.qml b/applets/webbrowser/qml/main.qml
index 38c005eb0..85f8fa6fb 100644
--- a/applets/webbrowser/qml/main.qml
+++ b/applets/webbrowser/qml/main.qml
@@ -322,7 +322,20 @@ PlasmoidItem {
                     }
                 }

+                // A certificate error waiting for the user to decide in certificateErrorMessage
+                property var pendingCertificateError: null
+
+                onCertificateError: error => {
+                    if (error.isMainFrame && error.overridable) {
+                        error.defer();
+                        pendingCertificateError = error;
+                    }
+                }
+
                 onLoadingChanged: loadingInfo => {
+                    if (loadingInfo.status !== WebEngineLoadingInfo.LoadStartedStatus) {
+                        pendingCertificateError = null;
+                    }
                     if (loadingInfo.status === WebEngineLoadingInfo.LoadStartedStatus) {
                         infoButton.dismiss();
                     } else if (loadingInfo.status === WebEngineLoadingInfo.LoadSucceededStatus) {
@@ -360,6 +373,33 @@ PlasmoidItem {
                 }
             }

+            Rectangle {
+                anchors.fill: parent
+                z: 2
+                visible: webview.pendingCertificateError !== null
+                color: Kirigami.Theme.backgroundColor
+                Kirigami.Theme.colorSet: Kirigami.Theme.View
+                Kirigami.Theme.inherit: false
+
+                PlasmaExtras.PlaceholderMessage {
+                    id: certificateErrorMessage
+                    anchors.centerIn: parent
+                    width: parent.width - Kirigami.Units.gridUnit * 4
+                    iconName: "security-low-symbolic"
+                    text: i18nc("@info", "The connection to this site is not secure")
+                    explanation: webview.pendingCertificateError?.description ?? ""
+                    helpfulAction: Kirigami.Action {
+                        icon.name: "security-low-symbolic"
+                        text: i18nc("@action:button load a page despite its certificate error", "Visit Anyway")
+                        onTriggered: {
+                            const error = webview.pendingCertificateError;
+                            webview.pendingCertificateError = null;
+                            error.acceptCertificate();
+                        }
+                    }
+                }
+            }
+
             MouseArea {
                 id: mouseArea
                 anchors.fill: parent
-- 
2.53.0
